const job = $json.job_opening;
const skillCount = Math.max(1, Math.min(Number($json.skill_count || 5), 10));

const prompt = `You are a recruitment analysis assistant.

Analyze this job opening and extract the top ${skillCount} weighted skills needed to screen candidates.

Rules:
- Return ONLY valid JSON.
- Do not include markdown.
- Do not include explanation.
- Return exactly ${skillCount} skills.
- Weights must sum to exactly 1.0.
- Use decimal weights, not percentages.
- Order from highest priority to lowest.
- Skill names must be practical recruiter-facing skills.
- Do not add generic soft skills unless clearly required.

Job opening:
${JSON.stringify(job, null, 2)}

Return this exact JSON structure:
{
  "skills": [
    {
      "skill_name": "string",
      "weight": 0.30,
      "order": 1
    }
  ]
}`;

return [{
  json: {
    ...$json,
    prompt
  }
}];

function parseJson(value) {
  if (typeof value === 'object' && value !== null) return value;
  if (typeof value !== 'string') throw new Error('AI output is not a string or object');

  let text = value.trim()
    .replace(/^```json\s*/i, '')
    .replace(/^```\s*/i, '')
    .replace(/```$/i, '')
    .trim();

  const first = text.indexOf('{');
  const last = text.lastIndexOf('}');
  if (first >= 0 && last > first) text = text.slice(first, last + 1);

  return JSON.parse(text);
}

const original = $('Set - Extract Request Data1').first().json;
const raw = $json.output || $json.text || $json.response || $json.message;
const parsed = parseJson(raw);

if (!Array.isArray(parsed.skills)) {
  throw new Error('AI response must contain skills array');
}

const skillCount = Math.max(1, Math.min(Number(original.skill_count || 5), 10));

let skills = parsed.skills
  .slice(0, skillCount)
  .map((s, index) => ({
    id: `sk-${Date.now()}-${index + 1}`,
    job_opening_id: original.job_opening.job_opening_id,
    name: String(s.skill_name || s.name || '').trim(),
    skill_name: String(s.skill_name || s.name || '').trim(),
    weight: Number(s.weight || 0),
    skill_order: Number(s.order || s.skill_order || index + 1),
    approved: false
  }))
  .filter(s => s.skill_name && s.weight > 0);

if (skills.length !== skillCount) {
  throw new Error(`Expected ${skillCount} skills, received ${skills.length}`);
}

let total = skills.reduce((sum, s) => sum + s.weight, 0);
if (!total) throw new Error('Total skill weight is zero');

if (Math.abs(total - 1) > 0.001) {
  skills = skills.map(s => ({ ...s, weight: Number((s.weight / total).toFixed(4)) }));
  const adjustedTotal = skills.reduce((sum, s) => sum + s.weight, 0);
  skills[skills.length - 1].weight = Number((skills[skills.length - 1].weight + (1 - adjustedTotal)).toFixed(4));
}

skills = skills
  .sort((a, b) => b.weight - a.weight)
  .map((s, index) => ({
    ...s,
    skill_order: index + 1
  }));

return [{
  json: {
    request_id: original.request_id,
    automation_type: original.automation_type,
    status: 'success',
    processing_status: 'skill_approval',
    job_opening_id: original.job_opening.job_opening_id,
    skill_count: skills.length,
    callback_url: original.callback_url,
    authorization: original.authorization,
    skills,
    processed_at: new Date().toISOString(),
    errors: []
  }
}];

